// Extract payload from Webhook
const payload = $input.first().json.body || $input.first().json;
const product = payload.product || {};
const subscribers = payload.subscribers || [];

const outputItems = [];

for (const sub of subscribers) {
  if (sub.email_consent && sub.email && sub.email.trim() !== '') {
    outputItems.push({
      json: {
        subscriber_id: sub.id,
        email: sub.email.trim(),
        whatsapp_number: sub.whatsapp_number || '',
        email_consent: sub.email_consent,
        whatsapp_consent: sub.whatsapp_consent,
        product_id: product.id || '',
        product_slug: product.slug || '',
        product_name_ar: product.name_ar || 'منتج جديد من ENGINITY',
        product_name_en: product.name_en || 'New ENGINITY Product',
        product_price: product.price_egp || 0,
        cover_path: product.cover_path || '',
        product_url: product.product_url || 'https://enginity-store-s8dx.vercel.app',
        launch_announcement: product.launch_announcement || '',
        launched_at: payload.timestamp || new Date().toISOString()
      }
    });
  }
}

if (outputItems.length === 0) {
  return [{ json: { notice: 'No email consented subscribers found in launch payload.' } }];
}

return outputItems;
